  function updateSave(){const target=$('#save-state');target.className='save-state '+(state.dirty?'dirty':'');target.innerHTML='<i></i>'+(state.dirty?'未保存':'示例工程');$('#undo').disabled=!state.history.length;$('#redo').disabled=!state.future.length;}
