  function stop(){document.querySelectorAll('#preview-frame video').forEach(v=>v.pause());state.playing=false;cancelAnimationFrame(frame);frame=0;const play=$('#play-preview');if(play){play.innerHTML=icon('play');play.setAttribute('aria-label','播放排版预演');}}
  function updateHeader(){const p=project();$('#project-name').textContent=p.name;$('#mode-summary').textContent=state.mode==='oral'?`${p.subtype} · ${p.template===0?'简洁口播':'新闻播报'}`:`${p.shots.length} 个镜头 · ${total().toFixed(1)} 秒`;$('.generation-count').textContent=p.count+' 条';$$('[data-mode]').forEach(b=>{const on=b.dataset.mode===state.mode;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1;b.setAttribute('aria-controls','workspace');});$('#assets-toggle').setAttribute('aria-expanded',state.assetsOpen);$('#workspace').classList.toggle('assets-hidden',!state.assetsOpen);}
