  function generateDialog(){const p=project();if(!p.shots.length&&state.mode!=='oral'){toast('先添加一个镜头');return;}openDialog('生成成片',`<div class="result-sheet"><img src="${state.mode==='oral'?asset('person').src:asset(selected()?.asset).src}" alt="当前封面"><div><h3>${esc(p.name)}</h3><p>${({quick:'一键成片',mix:'批量混剪',storyboard:'分镜脚本',oral:'口播'})[state.mode]} · <b>${p.count} 条</b><br>${p.ratio} · ${p.resolution} · ${p.fps} FPS<br>${state.mode==='oral'?esc(p.subtype):p.shots.length+' 个镜头 · 当前编排 '+total().toFixed(1)+' 秒'}</p></div></div>${field('成片保存位置','<select id="output-group"><option>周末到店宣传</option><option>新建成片组…</option></select>')}<div id="new-group-host"></div><table class="review-table"><tr><td>预计消耗</td><td>— TP</td></tr><tr><td>当前状态</td><td>交互原型 · 未连接生成服务</td></tr></table><p class="inline-note" style="margin-top:13px">此处仅演示确认、进度与返回编辑的交互，不创建真实任务、不扣 TP。</p>`,[{label:'返回编辑',fn:closeDialog},{label:'预演提交流程',class:'ai',fn:()=>{openDialog('原型流程预演',`<div class="done-mark">${icon('check')}</div><h3 class="done-heading">确认流程已走通</h3><p class="inline-note">${esc(p.name)} · ${p.count} 条 · ${p.ratio}<br>正式接入后，任务可在「工程与成片」追踪。此次没有生成视频或扣费。</p><div class="modal-note" style="margin-top:18px">你可以继续调整镜头、字幕与包装，或切换其他剪辑模式审阅。</div>`,[{label:'返回继续编辑',class:'dark',fn:closeDialog}],490);}}],540);$('#output-group').onchange=e=>$('#new-group-host').innerHTML=e.target.value.includes('新建')?field('成片组名称','<input aria-label="成片组名称" placeholder="例如：十月新品宣传">'):'';}
  function projectDialog(){openDialog('工程',`<div class="review-list"><div><strong>01</strong><div><b>本机原型草稿</b><p>仅保存在此浏览器，不读取或覆盖商家真实工程。</p></div><span class="spacer"></span><button class="button compact" id="open-draft">打开草稿</button></div><div><strong>02</strong><div><b>新建空白工程</b><p>保留当前示例，可通过撤销返回。</p></div><span class="spacer"></span><button class="button compact" id="new-project">新建</button></div><div><strong>03</strong><div><b>保存为模板</b><p>在原型中记录一份本机模板快照。</p></div><span class="spacer"></span><button class="button compact" id="save-template">保存模板</button></div></div>`,[{label:'关闭',fn:closeDialog}],620);$('#open-draft').onclick=()=>{try{const data=JSON.parse(localStorage.getItem(storageKey)||'null');if(!data?.projects){toast('尚未保存原型草稿');return;}remember();state.projects=data.projects;state.mode=data.mode;renderAll();closeDialog();toast('已打开本机原型草稿');}catch{toast('草稿格式不可用，当前工程保持不变');}};$('#new-project').onclick=()=>{change(()=>{project().shots=[];project().name='未命名工程';project().selected='';state.time=0;});closeDialog();};$('#save-template').onclick=()=>{try{localStorage.setItem(storageKey+'.template',JSON.stringify(project()));toast('原型模板已保存到此浏览器');closeDialog();}catch{toast('浏览器存储不可用');}};}
